"""Hidden behavioral tests for jo: json_values. Generated by pbkit from the gold binary."""


def test_inline_json_00(run):
    'value parsed as JSON: \'["\\\\"q\\\\"", "\\\\\\\\", "\\\\/", "\\\\b\\\\f\\\\n\\\\r\\\\t"]\''
    r = run(args=['v=["\\"q\\"", "\\\\", "\\/", "\\b\\f\\n\\r\\t"]'])
    assert r.stdout == b'{"v":["\\"q\\"","\\\\","/","\\b\\f\\n\\r\\t"]}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_file_json_00(run):
    r = run(args=['v=:d.json'], files={'d.json': b'["\\"q\\"", "\\\\", "\\/", "\\b\\f\\n\\r\\t"]'})
    assert r.stdout == b'{"v":["\\"q\\"","\\\\","/","\\b\\f\\n\\r\\t"]}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_input_json_00(run):
    r = run(args=['-f', 'd.json', 'x=1'], files={'d.json': b'["\\"q\\"", "\\\\", "\\/", "\\b\\f\\n\\r\\t"]'})
    assert r.stdout == b'["\\"q\\"","\\\\","/","\\b\\f\\n\\r\\t","x=1"]\n'
    assert r.stderr == b''
    assert r.returncode == 0


